// LoadConfig reads config values from a file and returns the config.
func LoadConfig(configFilePath string) (*Config, error) {
	var config Config

	b, err := ioutil.ReadFile(configFilePath)
	if err != nil {
		return nil, err
	}

	err = yaml.Unmarshal(b, &config)
	if err != nil {
		return nil, err
	}

	return &config, nil
}

